function currentMarkdown(){
  const a=interpret(currentReading);
  const entries=currentReading.cards.map(e=>{
    const c=cards.find(x=>x.id===e.cardId);
    return `### ${e.positionName} — ${c?c.name:e.cardId}\n\n${c?c.core:""}\n\n${e.positionMeaning}`;
  }).join("\n\n");
  return `# ${currentReading.spreadName}\n\n**Вопрос:** ${currentReading.question}\n\n**Тема:** ${currentReading.domain||"Общая ситуация"}\n\n**Дата:** ${fmtDate(currentReading.createdAt)}\n\n## Прямой ответ\n\n${a.answer}\n\n## Карты\n\n${entries}\n\n## Синтез\n\n${a.synthesis}\n\n## Практический шаг\n\n${a.nextStep}\n\n## Заметки\n\n${currentReading.notes||"—"}\n\n## Сверка с реальностью\n\n${currentReading.realityNote||"—"}\n\n---\n\nСимволическая интерпретация, не установленный факт.`;
}
function loadCanvasImage(src){
  return new Promise((resolve,reject)=>{
    const img=new Image();
    img.onload=()=>resolve(img);
    img.onerror=()=>reject(new Error("image failed"));
    img.src=src;
  });
}
function wrapCanvasText(ctx,text,maxWidth){
  const words=String(text||"").replace(/\s+/g," ").trim().split(" ");
  const lines=[];let line="";
  for(const word of words){
    const test=line?line+" "+word:word;
    if(ctx.measureText(test).width>maxWidth&&line){lines.push(line);line=word}
    else line=test;
  }
  if(line)lines.push(line);
  return lines;
}
async function shareReadingImage(){
  const canvas=document.createElement("canvas");
  canvas.width=1080;canvas.height=1350;
  const ctx=canvas.getContext("2d");
  if(!ctx){toast("Не удалось создать открытку");return}
  try{
    const grad=ctx.createLinearGradient(0,0,1080,1350);
    grad.addColorStop(0,"#07060c");grad.addColorStop(.55,"#151024");grad.addColorStop(1,"#0d0a18");
    ctx.fillStyle=grad;ctx.fillRect(0,0,1080,1350);
    for(let i=0;i<150;i++){
      const x=(i*457+83)%1044+18,y=(i*733+149)%780+120;
      ctx.fillStyle=i%9===0?"rgba(232,204,147,.75)":"rgba(247,240,228,.28)";
      ctx.beginPath();ctx.arc(x,y,i%11===0?1.8:1,0,Math.PI*2);ctx.fill();
    }
    ctx.strokeStyle="rgba(232,204,147,.32)";ctx.lineWidth=2;ctx.strokeRect(44,44,992,1262);
    ctx.textAlign="center";
    ctx.fillStyle="#e8cc93";ctx.font="600 30px Georgia, serif";
    ctx.fillText("NOCTURNE · ТАРО",540,124);
    ctx.fillStyle="#f7f0e4";ctx.font="500 52px Georgia, serif";
    const titleLines=wrapCanvasText(ctx,currentReading.spreadName,860).slice(0,2);
    titleLines.forEach((line,i)=>ctx.fillText(line,540,205+i*62));
    ctx.fillStyle="#aaa3c0";ctx.font="28px system-ui, sans-serif";
    const qLines=wrapCanvasText(ctx,currentReading.question,860).slice(0,3);
    qLines.forEach((line,i)=>ctx.fillText(line,540,315+i*38));
    const ids=currentReading.cards.slice(0,3).map(c=>c.cardId);
    const imgs=await Promise.all(ids.map(id=>loadCanvasImage("./assets/cards/"+id+".svg")));
    const w=230,h=345,gap=34,total=imgs.length*w+(imgs.length-1)*gap;
    let x=(1080-total)/2;const y=455;
    imgs.forEach((img,i)=>{
      ctx.save();
      ctx.translate(x+w/2,y+h/2);
      ctx.rotate((i-(imgs.length-1)/2)*0.055);
      ctx.shadowColor="rgba(0,0,0,.6)";ctx.shadowBlur=34;
      ctx.drawImage(img,-w/2,-h/2,w,h);
      ctx.restore();
      x+=w+gap;
    });
    const a=interpret(currentReading);
    ctx.fillStyle="#e8cc93";ctx.font="600 24px system-ui, sans-serif";
    ctx.fillText("ПРЯМОЙ ОТВЕТ",540,905);
    ctx.fillStyle="#f7f0e4";ctx.font="31px system-ui, sans-serif";
    const aLines=wrapCanvasText(ctx,a.answer,840).slice(0,6);
    aLines.forEach((line,i)=>ctx.fillText(line,540,955+i*42));
    ctx.fillStyle="#827b9a";ctx.font="24px system-ui, sans-serif";
    ctx.fillText("Символическая интерпретация · не установленный факт",540,1235);
    ctx.fillStyle="#e8cc93";ctx.font="600 20px system-ui, sans-serif";
    ctx.fillText("nocturne tarot",540,1275);
    const blob=await new Promise(res=>canvas.toBlob(res,"image/png"));
    if(!blob)throw new Error("no blob");
    const file=new File([blob],"nocturne-reading.png",{type:"image/png"});
    if(navigator.canShare&&navigator.canShare({files:[file]})){
      await navigator.share({files:[file],title:"Nocturne Tarot — "+currentReading.spreadName});
    }else{
      const url=URL.createObjectURL(blob),link=document.createElement("a");
      link.href=url;link.download="nocturne-reading.png";document.body.appendChild(link);link.click();link.remove();
      setTimeout(()=>URL.revokeObjectURL(url),1500);
      toast("Открытка сохранена как PNG");
    }
  }catch(e){
    console.error("Nocturne share image failed",e);
    toast("Не удалось собрать открытку. Попробуйте скачать TXT.");
  }
}

